#!/usr/bin/env python3
"""Generates perf_work.cpp, the 2 000-line translation unit of fixture `perf` (WP-27), and the edits.

perf_work.cpp is checked in; run this script from anywhere to regenerate it and the edits
(edits/value_2.edit, edits/stacked/value_3.edit ... value_6.edit). The output is deterministic.
"""
import pathlib

TOTAL_LINES = 2000
FUNCS = 130
HEADER = [
    "// Fixture `perf` (WP-27): one translation unit of exactly 2000 lines, the size the compile -> applied budget is",
    "// stated for. perf_fn_NNNN() are small, non-inlined functions with loops and branches; perf_checksum() calls all of",
    "// them; perf_value() (the last function) is what the edits change. Generated by gen_perf_tu.py: do not edit by hand.",
    '#include "perf.h"',
    "",
]


def function(n):
    k = n % 7
    return [
        f"__declspec(noinline) unsigned perf_fn_{n:04d}(unsigned x)",
        "{",
        f"    unsigned acc = x + {n}u;",
        f"    for (unsigned i = 0; i < {3 + k}u; ++i) {{",
        f"        acc = acc * {31 + 2 * k}u + i;",
        "        if ((acc & 1u) != 0u) {",
        f"            acc ^= 0x{(0x5bd1e995 + n * 977) & 0xFFFFFFFF:08x}u;",
        "        } else {",
        f"            acc += {n % 13 + 1}u;",
        "        }",
        "    }",
        f"    return acc + {n}u;",
        "}",
        "",
    ]


def checksum():
    lines = ["unsigned perf_checksum()", "{", "    unsigned sum = 0u;"]
    lines += [f"    sum += perf_fn_{n:04d}(sum);" for n in range(FUNCS)]
    lines += ["    return sum;", "}", ""]
    return lines


def tail(value):
    return ["int perf_value()", "{", f"    return {value};", "}"]


def build(value):
    lines = list(HEADER)
    for n in range(FUNCS):
        lines += function(n)
    lines += checksum()
    pad = TOTAL_LINES - len(lines) - len(tail(value))
    assert pad >= 0, pad
    lines += [f"// padding {i}" for i in range(pad)]
    lines += tail(value)
    assert len(lines) == TOTAL_LINES, len(lines)
    return lines


def diff(old, new, name):
    # One hunk: the `return N;` line of perf_value() with its context (difflib would also pair the closing brace).
    i = len(old) - 2
    assert old[i].startswith("    return ") and old[:i] == new[:i] and old[i + 1:] == new[i + 1:]
    start = i - 3  # three context lines before, one after
    lines = [f"--- a/{name}\n", f"+++ b/{name}\n", f"@@ -{start + 1},5 +{start + 1},5 @@\n"]
    lines += [" " + l + "\n" for l in old[start:i]]
    lines += ["-" + old[i] + "\n", "+" + new[i] + "\n", " " + old[i + 1] + "\n"]
    return "".join(lines)


def write(path, text):
    with open(path, "w", newline="\n") as f:
        f.write(text)


def main():
    here = pathlib.Path(__file__).parent
    versions = {v: build(v) for v in range(1, 7)}
    write(here / "perf_work.cpp", "\n".join(versions[1]) + "\n")
    write(here / "edits" / "value_2.edit", diff(versions[1], versions[2], "perf_work.cpp"))
    for v in range(3, 7):
        write(here / "edits" / "stacked" / f"value_{v}.edit", diff(versions[v - 1], versions[v], "perf_work.cpp"))


main()
